120	
121	## Parsing at Boundaries
122	
123	```rust
124	// Parse at the system boundary (API, CLI, config file)
125	struct Response {
126	    email: Email,
127	    age: Age,
128	    username: Username,
129	}
130	
131	fn handle_request(raw: RawRequest) -> Result<Response, Error> {
132	    // Parse ALL inputs upfront
133	    let email = Email::parse(&raw.email)?;
134	    let age = Age::parse(raw.age)?;
135	    let username = Username::parse(&raw.username)?;
136	    
137	    // Now work with validated types
138	    Ok(process_user(email, age, username))
139	}
140	
141	fn process_user(email: Email, age: Age, username: Username) -> Response {
142	    // This example builds a response from the validated inputs.
143	    Response { email, age, username }
144	}
145	```
